// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    W_WALLET c;

    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(uint256 unlockTime, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        // Actor's own address is the caller and the recipient; the call goes to an EOA (the test contract's
        // externally owned msg.sender), which always accepts value, so no adversarial helper is required:
        // the difference is in WHEN c lets the state write happen, which is visible via c's public getter.
        vm.assume(unlockTime > 0);
        vm.assume(amount > 0 && amount <= 100 ether);

        uint256 start = unlockTime; // choose a timestamp so that the boundary is reachable
        vm.warp(start);

        address actor = address(0xA11CE);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        // Right at the boundary (block.timestamp == unlockTime).
        // Reference (strict >): collection must NOT be allowed -> balance stays at `amount`.
        // Mutant (>=): collection IS allowed -> balance drops to zero.
        bool ok;
        vm.prank(actor);
        try c.Collect(amount) { ok = true; } catch { ok = false; }

        (, uint256 balanceAfter) = c.Acc(actor);

        // General rule: at the exact unlock timestamp, the caller's stored balance must still be the
        // deposited amount (collection is forbidden at the boundary).
        assertTrue(balanceAfter == amount);
    }
}
